source('common.R')
f <- list.files(root,pattern='_parameters\\.txt$',recursive=TRUE,full.names=TRUE)
if(!length(f)) stop('No parameter files in ',root)
m <- rbindlist(lapply(f,function(p){ d<-fread(p); stopifnot(nrow(d)==1); d[,run_dir:=dirname(p)]; d[,model:=if('R'%in%names(d)) 'Competition' else 'Hard']; if(d$model=='Hard') d[,`:=`(R=0,D=0)]; st<-list.files(dirname(p),pattern='_status\\.txt$',full.names=TRUE); d[,status:='incomplete']; if(length(st)==1) { z<-readLines(st,warn=FALSE); if(length(z)) d[,status:=strsplit(z[1],'\t')[[1]][1]] }; d }),fill=TRUE)
if(anyDuplicated(m[,c(keys,'seed'),with=FALSE])) stop('Duplicate treatment/seed')
write(m,'manifest'); write(m[,.N,by=c(keys,'status')],'replicate_coverage')
if(any(m$status!='completed')) warning('Incomplete/extinct runs excluded; see manifest')
m<-m[status=='completed']; if(!nrow(m)) stop('No completed runs')
res<-lapply(seq_len(nrow(m)),function(i){ a<-m[i]; d<-fread(file_one(a$run_dir,'_maxq_10-15k\\.txt$')); t<-fread(file_one(a$run_dir,'_trackedmutations_10-15k\\.txt$'),select=c('Mutation_ID','Event','q')); ids<-t[Event=='tracked',Mutation_ID]; if(anyDuplicated(ids)||anyDuplicated(d$Mutation_ID)||!setequal(ids,d$Mutation_ID)) stop('Tracking/MaxQ mismatch: ',a$run_dir); if(any(!is.finite(d$Max_q)|d$Max_q<0|d$Max_q>1)) stop('Invalid Max_q'); if(!length(ids)) warning('No registered mutations: ',a$run_dir); attach_meta(data.table(threshold=c(.05,.1,.2,.5,1),n_tracked=length(ids),n_crossed=vapply(c(.05,.1,.2,.5,1),function(q) sum(d$Max_q>=q),integer(1))),a) })
write(rbindlist(res),'threshold_by_seed')
